  'dl.driverbefore': { en: 'Driver before impact', ta: 'மோதலுக்கு முன் ஓட்டுநர்', hi: 'टक्कर से पहले चालक' },
  'dl.score': { en: 'Alertness score {s} ({tier})', ta: 'விழிப்பு மதிப்பெண் {s} ({tier})', hi: 'सतर्कता स्कोर {s} ({tier})' },
