  'rep.noblur': { en: 'No faces or plates needed blurring.', ta: 'முகங்களையோ எண் தகடுகளையோ மங்கலாக்கத் தேவையில்லை.', hi: 'किसी चेहरे या नंबर प्लेट को धुंधला करने की ज़रूरत नहीं थी।' },
  'rep.noloc': { en: 'No location was recorded. Open the site and place it on the map so a crew can find it.', ta: 'இருப்பிடம் பதிவாகவில்லை. குழுவினர் கண்டுபிடிக்க, அந்த இடத்தைத் திறந்து வரைபடத்தில் அமையுங்கள்.', hi: 'कोई लोकेशन दर्ज नहीं हुई। साइट खोलकर उसे नक्शे पर रखें ताकि दल उसे ढूंढ सके।' },
  'rep.classical': { en: 'The trained detection model is not installed, so a basic image method was used. Run scripts/get_model.py on the server for reliable results.', ta: 'பயிற்சி பெற்ற கண்டறிதல் மாதிரி நிறுவப்படவில்லை, எனவே அடிப்படை பட முறை பயன்படுத்தப்பட்டது. நம்பகமான முடிவுகளுக்கு சேவையகத்தில் scripts/get_model.py இயக்கவும்.', hi: 'प्रशिक्षित पहचान मॉडल इंस्टॉल नहीं है, इसलिए बुनियादी इमेज विधि इस्तेमाल हुई। भरोसेमंद नतीजों के लिए सर्वर पर scripts/get_model.py चलाएं।' },
  'rep.another': { en: 'Report another', ta: 'மற்றொன்றைப் புகாரளி', hi: 'एक और रिपोर्ट करें' },
